'use strict';

// MODULES //

var join = require( 'path' ).join;
var writeFileSync = require( '@stdlib/fs/write-file' ).sync;
var dtypes = require( '@stdlib/ndarray/dtypes' );
var currentYear = require( '@stdlib/time/current-year' );


// VARIABLES //

var FUNCTION_NAME = 'abs';
var KERNEL_MAP = {
	'float64': 'stdlib_base_abs',
	'float32': 'stdlib_base_absf',
	'complex128': 'stdlib_base_cabs',
	'complex64': 'stdlib_base_cabsf',
	'int32': 'stdlib_base_labs',
	'int16': 'stdlib_base_labs',
	'int8': 'stdlib_base_labs',
	'uint32': 'stdlib_base_abs',
	'uint16': 'stdlib_base_abs',
	'uint8': 'stdlib_base_abs',
	'uint8c': 'stdlib_base_abs'
};
var INCLUDE_MAP = {
	'abs': 'abs.h',
	'absf': 'absf.h',
	'cabs': 'cabs.h',
	'cabsf': 'cabsf.h',
	'labs': 'labs.h'
};

/**
* Default output dtype rule for abs function.
*
* @private
* @param {string} input - input dtype
* @returns {Array<string>} array of valid output dtypes
*/
function outputDtypeRule( input ) {
	var rules = {
		'float64': [ 'float64' ],
		'float32': [ 'float32', 'float64' ],
		'complex128': [ 'float64' ],
		'complex64': [ 'float32', 'float64' ],
		'int32': [ 'int32', 'uint32', 'float64' ],
		'int16': [ 'int16', 'int32', 'uint16', 'uint32', 'float32', 'float64' ],
		'int8': [ 'int8', 'int16', 'int32', 'uint8', 'uint8c', 'uint16', 'uint32', 'float32', 'float64' ],
		'uint32': [ 'uint32', 'float64' ],
		'uint16': [ 'int32', 'uint16', 'uint32', 'float32', 'float64' ],
		'uint8': [ 'int16', 'int32', 'uint8', 'uint8c', 'uint16', 'uint32', 'float32', 'float64' ],
		'uint8c': [ 'int16', 'int32', 'uint8', 'uint8c', 'uint16', 'uint32', 'float32', 'float64' ]
	};
	return rules[ input ] || [];
}

/**
* Generates the ndarray function name for given input and output dtypes.
*
* @private
* @param {string} input - input dtype
* @param {string} output - output dtype
* @returns {string} ndarray function name
*/
function getNdarrayFcnName( input, output ) {
	var map = {
		'float64': 'd',
		'float32': 'f',
		'complex128': 'z',
		'complex64': 'c',
		'int32': 'i',
		'int16': 'k',
		'int8': 's',
		'uint32': 'u',
		'uint16': 't',
		'uint8': 'b',
		'uint8c': 'a'
	};
	return 'stdlib_ndarray_' + map[ input ] + '_' + map[ output ];
}

/**
* Counts the number of functions in a group.
*
* @private
* @param {string} dt - dtype
* @param {Object} grouped - grouped functions
* @returns {number} count
*/
function countGroup( dt, grouped ) {
	return grouped[ dt ].length;
}

/**
* Generates function-specific includes.
*
* @private
* @returns {Array<string>} array of include statements
*/
function generateFunctionIncludes() {
	var includeStatement;
	var functionIncludes;
	var kernelNames;
	var includeKey;
	var kernel;
	var i;

	functionIncludes = [];
	kernelNames = Object.keys( KERNEL_MAP );
	for ( i = 0; i < kernelNames.length; i++ ) {
		kernel = KERNEL_MAP[ kernelNames[ i ] ];
		includeKey = kernel.replace( 'stdlib_base_', '' );
		if ( INCLUDE_MAP[ includeKey ] ) {
			includeStatement = '#include "stdlib/math/base/special/' + INCLUDE_MAP[ includeKey ] + '"';
			if ( functionIncludes.indexOf( includeStatement ) === -1 ) {
				functionIncludes.push( includeStatement );
			}
		}
	}
	return functionIncludes;
}

/**
* Generates type pairs and kernels.
*
* @private
* @returns {Object} object containing types and kernels arrays
*/
function generateTypesAndKernels() {
	var outputDtypes;
	var allDtypes;
	var kernels;
	var output;
	var input;
	var types;
	var i;
	var j;

	allDtypes = dtypes( 'all' );
	types = [];
	kernels = [];

	for ( i = 0; i < allDtypes.length; i++ ) {
		input = allDtypes[ i ];
		outputDtypes = outputDtypeRule( input );
		for ( j = 0; j < outputDtypes.length; j++ ) {
			output = outputDtypes[ j ];
			types.push( [ input, output ] );
			kernels.push( KERNEL_MAP[ input ] || 'stdlib_base_' + FUNCTION_NAME );
		}
	}

	return {
		'types': types,
		'kernels': kernels
	};
}

/**
* Main function to generate addon arrays.
*
* @private
*/
function main() {
	var functionIncludes;
	var licenseHeader;
	var baseIncludes;
	var dtypeOrder;
	var groupItems;
	var cHeader;
	var kernels;
	var grouped;
	var result;
	var types;
	var jsOut;
	var pair;
	var cOut;
	var obj;
	var dt;
	var i;
	var j;

	result = generateTypesAndKernels();
	types = result.types;
	kernels = result.kernels;

	dtypeOrder = [
		'float64', 'float32', 'generic', 'int32', 'int16', 'int8', 'uint32', 'uint16', 'uint8', 'uint8c'
	];
	grouped = {};

	for ( i = 0; i < dtypeOrder.length; i++ ) {
		grouped[ dtypeOrder[ i ] ] = [];
	}

	for ( i = 0; i < types.length; i++ ) {
		pair = types[ i ];
		if ( grouped[ pair[ 0 ] ] ) {
			grouped[ pair[ 0 ] ].push({
				'pair': pair,
				'kernel': kernels[ i ]
			});
		}
	}

	// Write generated_types.js:
	licenseHeader = '/**\n* @license Apache-2.0\n*\n* Copyright (c) ' + currentYear() + ' The Stdlib Authors.\n*\n* Licensed under the Apache License, Version 2.0 (the "License");\n* you may not use this file except in compliance with the License.\n* You may obtain a copy of the License at\n*\n*    http://www.apache.org/licenses/LICENSE-2.0\n*\n* Unless required by applicable law or agreed to in writing, software\n* distributed under the License is distributed on an "AS IS" BASIS,\n* WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n* See the License for the specific language governing permissions and\n* limitations under the License.\n*/\n\n/* eslint-disable array-element-newline */\n\n\'use strict\';\n\n// MODULES //\n\nvar dtypes = require( \'@stdlib/ndarray/dtypes\' );\n\n\n// MAIN //\n\nvar types = [\n';
	jsOut = licenseHeader;

	for ( i = 0; i < dtypeOrder.length; i++ ) {
		dt = dtypeOrder[ i ];
		groupItems = grouped[ dt ];
		for ( j = 0; j < groupItems.length; j++ ) {
			obj = groupItems[ j ];
			jsOut += '	dtypes.' + obj.pair[ 0 ] + ', dtypes.' + obj.pair[ 1 ] + ',\n';
		}
	}
	jsOut += '];\n\n\n// EXPORTS //\n\nmodule.exports = types;\n';
	writeFileSync( join( __dirname, '../lib/generated_types.js' ), jsOut, {
		'encoding': 'utf8'
	});

	// Write generated_addon_arrays.c:
	cHeader = '/**\n* @license Apache-2.0\n*\n* Copyright (c) ' + currentYear() + ' The Stdlib Authors.\n*\n* Licensed under the Apache License, Version 2.0 (the "License");\n* you may not use this file except in compliance with the License.\n* You may obtain a copy of the License at\n*\n*    http://www.apache.org/licenses/LICENSE-2.0\n*\n* Unless required by applicable law or agreed to in writing, software\n* distributed under the License is distributed on an "AS IS" BASIS,\n* WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n* See the License for the specific language governing permissions and\n* limitations under the License.\n*/\n\n';

	// Add base includes (always required for all math functions):
	baseIncludes = [
		'#include "stdlib/ndarray/base/function_object.h"',
		'#include "stdlib/ndarray/base/napi/unary.h"',
		'#include "stdlib/ndarray/base/unary.h"',
		'#include "stdlib/ndarray/dtypes.h"',
		'#include <stdint.h>'
	];
	cHeader += baseIncludes.join('\n') + '\n';

	// Add function-specific includes:
	functionIncludes = generateFunctionIncludes();
	if ( functionIncludes.length > 0 ) {
		cHeader += functionIncludes.join('\n') + '\n';
	}

	cOut = cHeader;
	cOut += '\n// Define a list of ndarray functions:\n';
	cOut += 'static ndarrayFcn functions[] = {\n';
	for ( i = 0; i < dtypeOrder.length; i++ ) {
		dt = dtypeOrder[ i ];
		if ( grouped[ dt ].length > 0 ) {
			cOut += '    // ' + dt + ' (' + countGroup( dt, grouped ) + ')\n';
			groupItems = grouped[ dt ];
			for ( j = 0; j < groupItems.length; j++ ) {
				obj = groupItems[ j ];
				cOut += '    ' + getNdarrayFcnName( obj.pair[ 0 ], obj.pair[ 1 ] ) + ',\n';
			}
		}
	}
	cOut += '};\n\n';
	cOut += '// Define the **ndarray** argument types for each ndarray function:\n';
	cOut += 'static int32_t types[] = {\n';
	for ( i = 0; i < dtypeOrder.length; i++ ) {
		dt = dtypeOrder[ i ];
		groupItems = grouped[ dt ];
		for ( j = 0; j < groupItems.length; j++ ) {
			obj = groupItems[ j ];
			cOut += '    STDLIB_NDARRAY_' + obj.pair[ 0 ].toUpperCase() + ', STDLIB_NDARRAY_' + obj.pair[ 1 ].toUpperCase() + ',\n';
		}
	}
	cOut += '};\n\n';
	cOut += '// Define a list of ndarray function "data" (in this case, callbacks):\n';
	cOut += 'static void *data[] = {\n';
	for ( i = 0; i < dtypeOrder.length; i++ ) {
		dt = dtypeOrder[ i ];
		if ( grouped[ dt ].length > 0 ) {
			cOut += '    // ' + dt + ' (' + countGroup( dt, grouped ) + ')\n';
			groupItems = grouped[ dt ];
			for ( j = 0; j < groupItems.length; j++ ) {
				obj = groupItems[ j ];
				cOut += '    (void *)' + obj.kernel + ',\n';
			}
		}
	}
	cOut += '};\n\n';
	cOut += '// Create an ndarray function object:\n';
	cOut += 'static const struct ndarrayFunctionObject obj = {\n';
	cOut += '    // ndarray function name:\n    name,\n\n';
	cOut += '    // Number of input ndarrays:\n    1,\n\n';
	cOut += '    // Number of output ndarrays:\n    1,\n\n';
	cOut += '    // Total number of ndarray arguments (nin + nout):\n    2,\n\n';
	cOut += '    // Array containing ndarray functions:\n    functions,\n\n';
	cOut += '    // Number of ndarray functions:\n    ' + types.length + ',\n\n';
	cOut += '    // Array of type "numbers" (as enumerated elsewhere), where the total number of types equals `narrays * nfunctions` and where each set of `narrays` consecutive types (non-overlapping) corresponds to the set of ndarray argument types for a corresponding ndarray function:\n    types,\n\n';
	cOut += '    // Array of void pointers corresponding to the "data" (e.g., callbacks) which should be passed to a respective ndarray function (note: the number of pointers should match the number of ndarray functions):\n    data\n};\n\n';
	cOut += 'STDLIB_NDARRAY_NAPI_MODULE_UNARY( obj )\n';
	writeFileSync( join( __dirname, '../src/generated_addon_arrays.c' ), cOut, {
		'encoding': 'utf8'
	});
}

main();
